(() => {
  const toggle=document.querySelector('.menu-toggle');
  const nav=document.querySelector('.mobile-nav');
  function closeMenu(){toggle.setAttribute('aria-expanded','false');nav.hidden=true;document.body.classList.remove('nav-open');}
  toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';if(open)closeMenu();else{toggle.setAttribute('aria-expanded','true');nav.hidden=false;document.body.classList.add('nav-open');}});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!nav.hidden){closeMenu();toggle.focus();}if(event.key==='Tab'&&!nav.hidden){const controls=[toggle,...nav.querySelectorAll('a')];const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
  matchMedia('(min-width:761px)').addEventListener('change',event=>{if(event.matches)closeMenu();});
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:.07});document.documentElement.classList.add('motion-ready');document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
  const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
  document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));let count=0;document.querySelectorAll('.menu-grid .dish-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;if(!card.hidden){count++;card.classList.add('is-visible');if(!reduceMotion.matches)card.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'none'}],{duration:400,easing:'ease-out'});}});document.querySelector('.menu-count').textContent=`${count}品をご紹介しています。`;}));
  const number=document.querySelector('.anniversary-number strong');
  if(number&&!reduceMotion.matches&&'IntersectionObserver'in window){const countObserver=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){countObserver.disconnect();number.setAttribute('aria-label','30');const start=performance.now();function count(now){const progress=Math.min((now-start)/1400,1);number.textContent=String(Math.round(30*(1-Math.pow(1-progress,3))));if(progress<1)requestAnimationFrame(count);}requestAnimationFrame(count);}},{threshold:.8});countObserver.observe(number);}
  const dialog=document.querySelector('.lightbox');
  if(dialog){const items=[...document.querySelectorAll('.gallery-open')];let index=0;let trigger=null;const photo=dialog.querySelector('img');function show(i){index=(i+items.length)%items.length;photo.src=items[index].dataset.full;photo.alt=items[index].dataset.caption;dialog.querySelector('figcaption').textContent=items[index].dataset.caption;dialog.querySelector('.lightbox-counter').textContent=`${index+1} / ${items.length}`;if(!reduceMotion.matches)photo.animate([{opacity:.3},{opacity:1}],{duration:300});}items.forEach((item,i)=>item.addEventListener('click',()=>{trigger=item;show(i);dialog.showModal();document.body.style.overflow='hidden';}));dialog.querySelector('.lightbox-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.lightbox-prev').addEventListener('click',()=>show(index-1));dialog.querySelector('.lightbox-next').addEventListener('click',()=>show(index+1));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('keydown',event=>{if(event.key==='ArrowLeft')show(index-1);if(event.key==='ArrowRight')show(index+1);});dialog.addEventListener('close',()=>{document.body.style.overflow='';trigger?.focus();});}
})();
